import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Settings — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"settings-02-how-tos-and-workflows.md","filePath":"settings-02-how-tos-and-workflows.md"}'),n={name:"settings-02-how-tos-and-workflows.md"};function r(s,e,l,g,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="settings-—-how-tos-workflows" tabindex="-1">Settings — How-tos &amp; Workflows <a class="header-anchor" href="#settings-—-how-tos-workflows" aria-label="Permalink to &quot;Settings — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for configuring your Lodestone workspace</em></p><hr><h2 id="updating-organization-details" tabindex="-1">Updating Organization Details <a class="header-anchor" href="#updating-organization-details" aria-label="Permalink to &quot;Updating Organization Details&quot;">​</a></h2><p><em>Admin only.</em></p><ol><li>Go to Settings &gt; Organization.</li><li>Update the <strong>Organization Name</strong>, <strong>Description</strong>, or <strong>Logo</strong> as needed.</li><li>Save changes.</li></ol><h3 id="writing-a-strong-organization-description" tabindex="-1">Writing a strong Organization Description <a class="header-anchor" href="#writing-a-strong-organization-description" aria-label="Permalink to &quot;Writing a strong Organization Description&quot;">​</a></h3><p>The Organization Description is used as context for all AI-generated Documents across the platform. The more specific and accurate it is, the more relevant the AI output will be.</p><p>A strong description covers:</p><ul><li>What your company does</li><li>Your industry and business model</li><li>Who your customers are</li><li>Any domain-specific context that would help an AI write on your behalf</li></ul><blockquote><p><strong>Example:</strong> &quot;We build project management software for mid-market construction firms. Our customers are project managers and site supervisors who need to coordinate complex multi-site builds. We sell primarily through a direct sales motion into companies with 100–500 employees.&quot;</p></blockquote><p>That level of specificity produces meaningfully better Document output than &quot;We build software for businesses.&quot;</p><hr><h2 id="archiving-and-unarchiving-your-organization" tabindex="-1">Archiving and Unarchiving Your Organization <a class="header-anchor" href="#archiving-and-unarchiving-your-organization" aria-label="Permalink to &quot;Archiving and Unarchiving Your Organization&quot;">​</a></h2><p><em>Admin only.</em></p><p>Archiving an organization removes access for all Builder members. Admins retain access and can unarchive at any time.</p><h3 id="to-archive" tabindex="-1">To archive <a class="header-anchor" href="#to-archive" aria-label="Permalink to &quot;To archive&quot;">​</a></h3><ol><li>Go to Settings &gt; Organization.</li><li>Select the Archive option.</li><li>Confirm. Builders immediately lose access to the workspace.</li></ol><h3 id="to-unarchive" tabindex="-1">To unarchive <a class="header-anchor" href="#to-unarchive" aria-label="Permalink to &quot;To unarchive&quot;">​</a></h3><ol><li>Log in as an Admin.</li><li>Go to Settings &gt; Organization.</li><li>Select Unarchive. Builder access is restored immediately.</li></ol><blockquote><p><strong>Use case:</strong> Archiving is useful when a workspace needs to be temporarily suspended — for example, during a team restructure or when transitioning between product phases.</p></blockquote><hr><h2 id="inviting-team-members" tabindex="-1">Inviting Team Members <a class="header-anchor" href="#inviting-team-members" aria-label="Permalink to &quot;Inviting Team Members&quot;">​</a></h2><p><em>Any member can invite; role assignment requires Admin.</em></p><ol><li>Go to Settings &gt; Team.</li><li>Enter the new member&#39;s email address.</li><li>Assign their role — <strong>Admin</strong> or <strong>Builder</strong>.</li><li>Send the invitation.</li></ol><p>The invited member receives an email with a link to join the workspace. Once they accept, they have immediate access based on their assigned role.</p><hr><h2 id="changing-a-member-s-role" tabindex="-1">Changing a Member&#39;s Role <a class="header-anchor" href="#changing-a-member-s-role" aria-label="Permalink to &quot;Changing a Member&#39;s Role&quot;">​</a></h2><p><em>Admin only.</em></p><ol><li>Go to Settings &gt; Team.</li><li>Find the member whose role you want to change.</li><li>Update their role to Admin or Builder.</li></ol><p>Role changes take effect immediately. Note that there must always be at least one Admin — you cannot demote the last Admin in a workspace.</p><hr><h2 id="removing-a-team-member" tabindex="-1">Removing a Team Member <a class="header-anchor" href="#removing-a-team-member" aria-label="Permalink to &quot;Removing a Team Member&quot;">​</a></h2><ol><li>Go to Settings &gt; Team.</li><li>Find the member you want to remove.</li><li>Select Remove.</li></ol><p>Removed members immediately lose access to the workspace. Their previously created content (Features, Documents, Roadmaps, etc.) remains in the workspace.</p><hr><h2 id="configuring-feature-status-stages" tabindex="-1">Configuring Feature Status Stages <a class="header-anchor" href="#configuring-feature-status-stages" aria-label="Permalink to &quot;Configuring Feature Status Stages&quot;">​</a></h2><ol><li>Go to Settings &gt; Modules, then select the <strong>Features</strong> sub-tab.</li><li>To <strong>rename</strong> a stage, click its name and edit it directly.</li><li>To <strong>add</strong> a new stage, use the Add Stage option and enter a name.</li><li>To <strong>delete</strong> a stage, select the delete option next to it.</li></ol><blockquote><p><strong>Important:</strong> Deleting a stage moves all Features currently in that stage to the default stage. Review which Features are in the stage before deleting to avoid unexpected status changes.</p></blockquote><p>Status stage changes apply immediately across the entire platform — the backlog, all Releases, and every view where Feature status appears.</p><hr><h2 id="configuring-feature-evaluation-criteria" tabindex="-1">Configuring Feature Evaluation Criteria <a class="header-anchor" href="#configuring-feature-evaluation-criteria" aria-label="Permalink to &quot;Configuring Feature Evaluation Criteria&quot;">​</a></h2><ol><li>Go to Settings &gt; Modules, then select the <strong>Features</strong> sub-tab.</li><li>Select a built-in framework (Value/Effort, RICE, ICE, WSJF, etc.), or choose to create a custom framework.</li><li>If creating a custom framework: <ul><li>Define each input field and its data type</li><li>Define the calculation formula</li></ul></li><li>Save. The new framework&#39;s fields appear in the Feature backlog and on Feature Detail pages.</li></ol><p>Only one evaluation framework is active at a time. Previously entered scores for an inactive framework are preserved and reappear if you switch back.</p><hr><h2 id="setting-the-strategy-default" tabindex="-1">Setting the Strategy Default <a class="header-anchor" href="#setting-the-strategy-default" aria-label="Permalink to &quot;Setting the Strategy Default&quot;">​</a></h2><ol><li>Go to Settings &gt; Modules &gt; Strategy Configuration.</li><li>Choose <strong>Top-Down</strong> or <strong>Bottom-Up</strong> as the workspace default.</li><li>Save.</li></ol><p>This sets the default approach when creating a new Strategy. It can be overridden at the point of creating any individual Strategy — the workspace default is a starting point, not a constraint.</p><hr><h2 id="configuring-object-types-taxonomy" tabindex="-1">Configuring Object Types (Taxonomy) <a class="header-anchor" href="#configuring-object-types-taxonomy" aria-label="Permalink to &quot;Configuring Object Types (Taxonomy)&quot;">​</a></h2><p><em>Admin only.</em></p><p>The Taxonomy tab lets you define the object types available in your workspace — such as Epics, Bugs, or Tasks — in addition to the built-in Feature type.</p><h3 id="creating-a-new-object-type" tabindex="-1">Creating a new object type <a class="header-anchor" href="#creating-a-new-object-type" aria-label="Permalink to &quot;Creating a new object type&quot;">​</a></h3><ol><li>Go to Settings &gt; Taxonomy.</li><li>Click <strong>Add Type</strong>.</li><li>Enter a <strong>Name</strong> (e.g. &quot;Epic&quot;) and a <strong>Prefix</strong> of 2–8 uppercase letters (e.g. &quot;EPIC&quot;). The prefix is used to generate typed IDs like EPIC-001.</li><li>Optionally configure <strong>Allowed Parent Types</strong> and <strong>Allowed Child Types</strong> to define valid hierarchy relationships for this type.</li><li>Save. The new type is immediately available for assignment in the Backlog.</li></ol><blockquote><p><strong>Note:</strong> The prefix cannot be changed after items have been assigned this type, as doing so would invalidate existing typed IDs. Choose prefixes deliberately.</p></blockquote><h3 id="renaming-an-object-type" tabindex="-1">Renaming an object type <a class="header-anchor" href="#renaming-an-object-type" aria-label="Permalink to &quot;Renaming an object type&quot;">​</a></h3><p>Type names can be updated at any time from Settings &gt; Taxonomy without affecting typed IDs — the prefix and sequential counter remain stable regardless of the display name.</p><h3 id="deleting-an-object-type" tabindex="-1">Deleting an object type <a class="header-anchor" href="#deleting-an-object-type" aria-label="Permalink to &quot;Deleting an object type&quot;">​</a></h3><p>Deleting a type requires reassigning all items currently using it. The delete dialog lists the number of items affected and prompts you to choose a replacement type. Items are reassigned before the type is removed.</p><h3 id="setting-the-top-tier-type" tabindex="-1">Setting the top-tier type <a class="header-anchor" href="#setting-the-top-tier-type" aria-label="Permalink to &quot;Setting the top-tier type&quot;">​</a></h3><p>The top-tier type represents the highest level in your hierarchy. To change it:</p><ol><li>Go to Settings &gt; Taxonomy.</li><li>Use the <strong>Top-Tier Type</strong> selector to choose the type that should sit at the top of your object hierarchy.</li><li>Save.</li></ol><hr><h2 id="managing-integrations" tabindex="-1">Managing Integrations <a class="header-anchor" href="#managing-integrations" aria-label="Permalink to &quot;Managing Integrations&quot;">​</a></h2><p>Integration setup and configuration is covered in detail in the Integrations module guide. To access integration settings:</p><ol><li>Go to Settings &gt; Integrations.</li><li>Find the integration you want to connect or configure.</li></ol><p>Currently available: Fireflies, Gong (Admin only to connect), and JIRA.</p><hr><h2 id="setting-up-multi-factor-authentication" tabindex="-1">Setting Up Multi-Factor Authentication <a class="header-anchor" href="#setting-up-multi-factor-authentication" aria-label="Permalink to &quot;Setting Up Multi-Factor Authentication&quot;">​</a></h2><p>Multi-factor authentication (MFA) is a personal account setting — it applies to your individual login, not to the organization. MFA is available to all users regardless of role.</p><p>To access MFA settings, navigate to <strong>Account &gt; Multi-Factor Authentication</strong> (this is separate from org-level Settings).</p><h3 id="totp-authenticator-app" tabindex="-1">TOTP (Authenticator App) <a class="header-anchor" href="#totp-authenticator-app" aria-label="Permalink to &quot;TOTP (Authenticator App)&quot;">​</a></h3><ol><li>Select <strong>Authenticator App</strong>.</li><li>Scan the QR code displayed on screen with your authenticator app (such as Google Authenticator, Authy, or 1Password).</li><li>Enter the verification code from your app to confirm setup.</li></ol><p>Once set up, you will be prompted to enter a code from your authenticator app on each login.</p><h3 id="sms" tabindex="-1">SMS <a class="header-anchor" href="#sms" aria-label="Permalink to &quot;SMS&quot;">​</a></h3><ol><li>Select <strong>SMS</strong>.</li><li>Enter your mobile phone number.</li><li>Enter the verification code sent to your phone to confirm setup.</li></ol><p>Once set up, you will receive a text message with a verification code on each login.</p><hr><h2 id="setting-up-passkeys" tabindex="-1">Setting Up Passkeys <a class="header-anchor" href="#setting-up-passkeys" aria-label="Permalink to &quot;Setting Up Passkeys&quot;">​</a></h2><p>Passkeys are a personal account setting — they apply to your individual login and are available to all users regardless of role. A passkey lets you sign in using your device&#39;s biometric sensor (fingerprint, face), PIN, or a hardware security key — no password required.</p><p>To access passkey settings, navigate to <strong>Account &gt; Passkeys</strong> (separate from org-level Settings).</p><h3 id="registering-a-passkey" tabindex="-1">Registering a passkey <a class="header-anchor" href="#registering-a-passkey" aria-label="Permalink to &quot;Registering a passkey&quot;">​</a></h3><ol><li>Go to <strong>Account &gt; Passkeys</strong>.</li><li>Optionally enter a name for the passkey (e.g. &quot;MacBook Touch ID&quot;) to identify it later.</li><li>Click <strong>Add Passkey</strong>.</li><li>Follow your device&#39;s prompt to complete registration using your fingerprint, face, or PIN.</li></ol><p>Once registered, you can sign in to Lodestone using the passkey instead of your password. When you next sign in from the same device, a &quot;Continue with Passkey&quot; button appears on the login page.</p><h3 id="setting-up-a-passkey-from-the-login-prompt" tabindex="-1">Setting up a passkey from the login prompt <a class="header-anchor" href="#setting-up-a-passkey-from-the-login-prompt" aria-label="Permalink to &quot;Setting up a passkey from the login prompt&quot;">​</a></h3><p>After signing in, Lodestone may show a one-time prompt to set up a passkey. You can click <strong>Set up passkey</strong> to register immediately, <strong>Maybe later</strong> to be prompted again next time, or <strong>Don&#39;t ask again</strong> to permanently dismiss the prompt.</p><h3 id="removing-a-passkey" tabindex="-1">Removing a passkey <a class="header-anchor" href="#removing-a-passkey" aria-label="Permalink to &quot;Removing a passkey&quot;">​</a></h3><ol><li>Go to <strong>Account &gt; Passkeys</strong>.</li><li>Click the delete icon next to the passkey you want to remove.</li></ol><p>Removing a passkey does not affect your password or other sign-in methods.</p><hr><p><em>Next: Advanced Features &amp; Customization — using Settings strategically, custom evaluation frameworks, and organizational configuration tips.</em></p>',91)])])}const d=t(n,[["render",r]]);export{u as __pageData,d as default};
